import OpenAI from "openai";

const client = new OpenAI({
  apiKey: process.env.NAN_API_KEY,
  baseURL: "https://api.nan.builders/v1",
});

// rerank isn't part of the OpenAI client, so call it directly:
const res = await fetch("https://api.nan.builders/v1/rerank", {
  method: "POST",
  headers: {
    Authorization: `Bearer ${process.env.NAN_API_KEY}`,
    "Content-Type": "application/json",
  },
  body: JSON.stringify({
    model: "rerank",
    query: "What is the capital of France?",
    documents: ["Paris is the capital of France.", "Berlin is the capital of Germany."],
  }),
});
const data = await res.json();
console.log(data.results);

import OpenAI from "openai";

const client = new OpenAI({
  apiKey: process.env.NAN_API_KEY,
  baseURL: "https://api.nan.builders/v1",
});

import fs from "node:fs";
const speech = await client.audio.speech.create({
  model: "kokoro",
  voice: "ef_dora",
  input: "Bienvenido a NaN.",
});
fs.writeFileSync("speech.mp3", Buffer.from(await speech.arrayBuffer()));

import OpenAI from "openai";

const client = new OpenAI({
  apiKey: process.env.NAN_API_KEY,
  baseURL: "https://api.nan.builders/v1",
});

import fs from "node:fs";
const resp = await client.audio.transcriptions.create({
  model: "whisper",
  file: fs.createReadStream("audio.mp3"),
});
console.log(resp.text);

