import OpenAI from "openai";

const client = new OpenAI({
  apiKey: process.env.NAN_API_KEY,
  baseURL: "https://api.nan.builders/v1",
});

const img = await client.images.generate({
  model: "flux-2-klein",
  prompt: "A lighthouse at sunset over cliffs",
  size: "1024x1024",
});
console.log(img.data[0].url);

import OpenAI from "openai";

const client = new OpenAI({
  apiKey: process.env.NAN_API_KEY,
  baseURL: "https://api.nan.builders/v1",
});

import fs from "node:fs";
const img = await client.images.edit({
  model: "flux-2-klein",
  image: fs.createReadStream("ref.png"),
  prompt: "Turn the scene into winter, with snow",
});
console.log(img.data[0].url);

// usage isn't part of the OpenAI SDK, so call it directly:
const res = await fetch("https://api.nan.builders/v1/usage?start_date=2026-01-01&end_date=2026-01-31", {
  headers: { Authorization: `Bearer ${process.env.NAN_API_KEY}` },
});
console.log(await res.json());

